param([Parameter(Mandatory=$true)][string]$JsonJar)
$ErrorActionPreference='Stop'
$root=Split-Path $PSScriptRoot -Parent
if(!(Test-Path -LiteralPath $JsonJar)){throw 'Pass a local org.json jar with -JsonJar (tested with 20240303).'}
$out=Join-Path $root '.build-secretary-inbox-tests'
New-Item -ItemType Directory -Force $out | Out-Null
$java='C:/Program Files/Android/Android Studio/jbr/bin'
$sources=@(Get-ChildItem "$PSScriptRoot/secretary-inbox-tests" -Recurse -Filter '*.java' | ForEach-Object FullName)
$sources+=@("$root/phone-app/src/com/example/rokidgeminisecretary/SecretaryInboxPresentation.java","$root/glass-app/src/com/example/rokidkeyboardbridge/KeepTopicImagePolicy.java","$root/glass-app/src/com/example/rokidkeyboardbridge/MeetingCameraPolicy.java","$root/glass-app/src/com/example/rokidkeyboardbridge/ProactiveDeliveryPolicy.java","$root/phone-app/src/com/example/rokidgeminisecretary/ImageAttachmentKinds.java","$root/glass-app/src/com/example/rokidkeyboardbridge/ImageAttachmentKinds.java","$root/phone-app/src/com/example/rokidgeminisecretary/ImageReferenceSummary.java","$root/phone-app/src/com/example/rokidgeminisecretary/WebRequestLedger.java","$root/phone-app/src/com/example/rokidgeminisecretary/SecretaryInbox.java","$root/phone-app/src/com/example/rokidgeminisecretary/ConversationRuntimeSnapshot.java","$root/phone-app/src/com/example/rokidgeminisecretary/TrackedWebRequest.java","$root/phone-app/src/com/example/rokidgeminisecretary/PhotoVaultCipher.java","$root/glass-app/src/com/example/rokidkeyboardbridge/SecretaryInboxPolicy.java","$root/glass-app/src/com/example/rokidkeyboardbridge/SecretaryIntent.java","$root/glass-app/src/com/example/rokidkeyboardbridge/ConversationContextReview.java","$root/glass-app/src/com/example/rokidkeyboardbridge/TrackedWebRequest.java","$root/glass-app/src/com/example/rokidkeyboardbridge/ConversationHandoffCard.java","$root/glass-app/src/com/example/rokidkeyboardbridge/ConversationTaskPolicy.java","$root/glass-app/src/com/example/rokidkeyboardbridge/ConversationProgressPolicy.java")
$sources+=@("$root/phone-app/src/com/example/rokidgeminisecretary/CalendarDraftEdits.java","$root/phone-app/src/com/example/rokidgeminisecretary/NavigationHealthPolicy.java","$root/glass-app/src/com/example/rokidkeyboardbridge/MeetingProgressPolicy.java")
$sources+=@("$root/phone-app/src/com/example/rokidgeminisecretary/OperationStatusPolicy.java","$root/phone-app/src/com/example/rokidgeminisecretary/TransferProgressPolicy.java","$root/glass-app/src/com/example/rokidkeyboardbridge/TransferProgressPolicy.java","$root/glass-app/src/com/example/rokidkeyboardbridge/MeetingReceiptPolicy.java","$root/glass-app/src/com/example/rokidkeyboardbridge/ReadPhotoReceiptPolicy.java")
$sources+=@("$root/phone-app/src/com/example/rokidgeminisecretary/WorkspaceCommandPolicy.java")
$sources+=@("$root/glass-app/src/com/example/rokidkeyboardbridge/NotificationDispatchGate.java","$root/glass-app/src/com/example/rokidkeyboardbridge/CodexNotificationPolicy.java")
$sources+=@("$root/glass-app/src/com/example/rokidkeyboardbridge/ImageReferenceSummary.java")
$sources+=@("$root/phone-app/src/com/example/rokidgeminisecretary/ReferenceDraftPolicy.java")
$sources+=@("$root/glass-app/src/com/example/rokidkeyboardbridge/LocalConversationStop.java")
$sources+=@("$root/glass-app/src/com/example/rokidkeyboardbridge/ConversationAnswerGuard.java","$root/glass-app/src/com/example/rokidkeyboardbridge/NormalRequestContextPolicy.java","$root/glass-app/src/com/example/rokidkeyboardbridge/ConversationCorrections.java","$root/glass-app/src/com/example/rokidkeyboardbridge/ConversationDeliveryState.java","$root/phone-app/src/com/example/rokidgeminisecretary/ConversationDeliveryState.java","$root/phone-app/src/com/example/rokidgeminisecretary/ConversationRecoveryStore.java","$root/glass-app/src/com/example/rokidkeyboardbridge/ConversationFailurePolicy.java","$root/glass-app/src/com/example/rokidkeyboardbridge/GeminiTextBudget.java","$root/glass-app/src/com/example/rokidkeyboardbridge/ConversationTopicBoundary.java","$root/glass-app/src/com/example/rokidkeyboardbridge/ConversationFollowupPolicy.java")
& "$java/javac.exe" -encoding UTF8 -cp $JsonJar -d $out @sources
if($LASTEXITCODE){throw 'Inbox test compilation failed'}
foreach($test in @('com.example.rokidkeyboardbridge.ConversationReliabilityTest','com.example.rokidgeminisecretary.ConversationRecoveryStoreTest','com.example.rokidkeyboardbridge.ConversationFailurePolicyTest','com.example.rokidkeyboardbridge.GeminiTextBudgetTest','com.example.rokidkeyboardbridge.ConversationContinuityMatrixTest','com.example.rokidgeminisecretary.ReferenceDraftPolicyTest','com.example.rokidkeyboardbridge.ImageReferenceSummaryTest','com.example.rokidkeyboardbridge.NotificationDispatchGateTest','com.example.rokidgeminisecretary.WorkspaceCommandPolicyTest','com.example.rokidgeminisecretary.OperationPolicyTest','com.example.rokidgeminisecretary.TransferPolicyTest','com.example.rokidkeyboardbridge.TransferPolicyTest','com.example.rokidkeyboardbridge.MeetingReceiptTest','com.example.rokidgeminisecretary.WorkspacePolicyTest','com.example.rokidkeyboardbridge.MeetingProgressPolicyTest','com.example.rokidgeminisecretary.SecretaryInboxPresentationTest','com.example.rokidkeyboardbridge.CapturePressurePolicyTest','com.example.rokidkeyboardbridge.ProactiveDeliveryPolicyTest','com.example.rokidgeminisecretary.ImageAttachmentKindsTest','com.example.rokidkeyboardbridge.ImageAttachmentKindsTest','com.example.rokidgeminisecretary.ImageReferenceSummaryTest','com.example.rokidgeminisecretary.WebRequestLedgerTest','com.example.rokidgeminisecretary.SecretaryInboxStoreTest','com.example.rokidgeminisecretary.ConversationRuntimeSnapshotTest','com.example.rokidgeminisecretary.TrackedWebRequestTest','com.example.rokidkeyboardbridge.SecretaryInboxPolicyTest','com.example.rokidkeyboardbridge.SecretaryIntentTest','com.example.rokidkeyboardbridge.ConversationContextReviewTest','com.example.rokidkeyboardbridge.TrackedWebRequestTest','com.example.rokidkeyboardbridge.ConversationHandoffCardTest')){
 & "$java/java.exe" -cp "$out;$JsonJar" $test
 if($LASTEXITCODE){throw "Inbox regression failed: $test"}
}
